<template>
  <main class="adminPage">
    <aside class="adminSidebar"><brandLogo /><span class="endLabel">平台端</span><nav><button v-for="item in sections" :key="item.id" :aria-current="section === item.id ? 'page' : undefined" @click="section = item.id"><component :is="item.icon" :size="20" />{{ item.label }}</button></nav><accountMenu /></aside>
    <section class="adminContent"><header class="pageHeader"><div><span class="eyebrow">AFXEN / 平台端</span><h1>{{ sections.find(item => item.id === section)?.label }}</h1></div><el-tag v-if="platform.scope === 'scenario'" type="warning">隔离预览 · 非真实业务数据</el-tag></header>
      <el-alert v-if="platformError" :title="platformError" type="error" :closable="false"><el-button @click="loadPlatform">重试</el-button></el-alert><p v-if="platformLoading" role="status">正在读取…</p>
      <template v-else-if="!platformError">
        <template v-if="section === 'customers'"><div class="sectionToolbar"><el-input v-model="customerSearch" placeholder="搜索客户名称" aria-label="搜索客户名称" clearable /><el-button type="primary" @click="openCustomer()">创建用户组</el-button></div>
          <el-table :data="filteredCustomers" emptyText="暂无用户组"><el-table-column type="index" label="序号" :width="70" /><el-table-column prop="name" label="客户名称" :minWidth="160" /><el-table-column label="状态" :minWidth="100"><template #default="{ row }"><el-tag :type="row.enabled === false ? 'info' : 'success'">{{ row.enabled === false ? '已禁用' : '已启用' }}</el-tag></template></el-table-column><el-table-column label="操作" :width="280" fixed="right"><template #default="{ row }"><div class="customerActions"><el-button text @click="openAccounts(row.id)">账号管理</el-button><el-button text @click="openCustomer(row as Customer)">编辑</el-button><el-button text :type="row.enabled === false ? 'primary' : 'danger'" :disabled="busy" @click="toggleCustomer(row as Customer)">{{ row.enabled === false ? '启用' : '禁用' }}</el-button><el-button text type="danger" :disabled="busy" @click="deleteCustomer(row as Customer)">删除</el-button></div></template></el-table-column></el-table>
        </template>
        <customerAccounts v-if="section === 'accounts'" :customerId="String(route.query.customerId || '')" />
        <template v-if="section === 'templates'"><div class="sectionToolbar"><p>仅平台管理员提交与维护</p><el-button type="primary" @click="openTemplate()">提交模板</el-button></div><el-table :data="state.templates" emptyText="暂无平台模板"><el-table-column prop="name" label="名称" /><el-table-column label="类型"><template #default="{ row }">{{ row.kind === 'project' ? '项目模板' : '视频模板' }}</template></el-table-column><el-table-column label="可见范围"><template #default="{ row }">{{ row.customerIds.length ? row.customerIds.map((id: string) => state.customers.find(item => item.id === id)?.name).join('、') : '全部客户' }}</template></el-table-column><el-table-column label="状态"><template #default="{ row }">{{ row.enabled ? '已发布' : '未发布' }}</template></el-table-column><el-table-column label="操作"><template #default="{ row }"><el-button text @click="openTemplate(row as PlatformTemplate)">内容与范围</el-button></template></el-table-column></el-table></template>
        <template v-if="section === 'usage'"><div class="usageFilters"><el-select v-model="usageCustomer" clearable placeholder="全部客户" aria-label="统计客户"><el-option v-for="item in state.customers" :key="item.id" :label="item.name" :value="item.id" /></el-select><el-select v-model="usageAccount" clearable placeholder="全部账号" aria-label="统计账号"><el-option v-for="item in usageAccounts" :key="item.id" :label="item.name" :value="item.id" /></el-select><el-select v-model="usageModel" clearable placeholder="全部模型" aria-label="统计模型"><el-option v-for="item in state.models" :key="item.id" :label="item.name" :value="item.id" /></el-select><el-date-picker v-model="usageDates" type="daterange" startPlaceholder="开始日期" endPlaceholder="结束日期" /></div><div class="usageSummary"><article v-for="status in ['all', 'completed', 'failed', 'running']" :key="status"><span>{{ status === 'all' ? '任务总数' : status === 'running' ? '处理中' : taskLabels[status as PlatformTask['status']] }}</span><strong>{{ usageTasks.filter(item => status === 'all' || (status === 'running' ? ['waiting','running','saving','unknown'].includes(item.status) : item.status === status)).length }}</strong></article></div><p>按实际单位分别记录；未返回用量不计作零。本期不收费，不展示私人提示词或生成结果。</p><el-table :data="usageTasks" emptyText="暂无用量记录"><el-table-column prop="modelId" label="模型" /><el-table-column label="状态"><template #default="{ row }">{{ taskLabels[row.status as PlatformTask['status']] }}</template></el-table-column><el-table-column prop="elapsed" label="耗时" /><el-table-column prop="usage" label="实际用量及单位" /><el-table-column label="时间"><template #default="{ row }">{{ formatDate(row.createdAt) }}</template></el-table-column></el-table></template>
      </template>
    </section>
    <el-dialog v-model="customerVisible" title="用户组" width="min(480px, 94vw)" :closeOnClickModal="false"><el-form v-if="customerDraft" labelPosition="top"><el-form-item label="客户名称" required><el-input v-model="customerDraft.name" :maxlength="100" /></el-form-item></el-form><p v-if="dialogError" role="alert" class="failure">{{ dialogError }}</p><template #footer><el-button @click="customerVisible = false">取消</el-button><el-button type="primary" :loading="busy" @click="saveCustomer">保存</el-button></template></el-dialog>
    <el-dialog v-model="templateVisible" title="平台模板内容与范围" width="min(640px, 94vw)" :closeOnClickModal="false"><el-form v-if="templateDraft" labelPosition="top"><el-form-item label="模板名称"><el-input v-model="templateDraft.name" /></el-form-item><el-form-item label="类型"><el-radio-group v-model="templateDraft.kind"><el-radio value="video">视频模板</el-radio><el-radio value="project">项目模板</el-radio></el-radio-group></el-form-item><el-form-item label="模板文件"><input ref="templateFileInput" type="file" :accept="templateDraft.kind === 'video' ? 'video/mp4' : 'application/json,.json'" hidden @change="pickTemplateFile" /><el-button @click="templateFileInput?.click()">选择{{ templateDraft.kind === 'video' ? '视频' : '项目快照' }}</el-button><span>{{ templateFile?.name || templateDraft.sourceName }}</span></el-form-item><el-form-item label="内容说明"><el-input v-model="templateDraft.description" type="textarea" :rows="4" /></el-form-item><el-form-item label="依赖模型"><el-select v-model="templateDraft.modelIds" multiple><el-option v-for="model in state.models" :key="model.id" :label="model.name" :value="model.id" /></el-select></el-form-item><el-form-item label="可见客户（不选为全部客户）"><el-select v-model="templateDraft.customerIds" multiple><el-option v-for="customer in state.customers" :key="customer.id" :label="customer.name" :value="customer.id" /></el-select></el-form-item><el-form-item label="发布"><el-switch v-model="templateDraft.enabled" /></el-form-item><p>隔离预览保留演示状态，不代表真实上传。正式文件保存由模板接口承接。</p></el-form><p v-if="dialogError" role="alert" class="failure">{{ dialogError }}</p><template #footer><el-button @click="templateVisible = false">取消</el-button><el-button type="primary" :loading="busy" @click="saveTemplate">保存</el-button></template></el-dialog>
  </main>
</template>
<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { ElMessage, ElMessageBox } from "element-plus";
import { IconUsers, IconUser, IconLayoutGrid, IconChartBar } from "@tabler/icons-vue";
import brandLogo from "@/components/brandLogo.vue";
import accountMenu from "@/components/accountMenu.vue";
import customerAccounts from "@/components/customerAccounts.vue";
import { platformState as state, loadPlatform, platformError, platformLoading, savePlatform } from "@/stores/platform";
import { platform, taskLabels, type Customer, type PlatformTemplate, type PlatformCommand, type PlatformTask } from "@/ports/platform";
const route = useRoute(), router = useRouter();
const sections = [{ id: "customers", label: "用户组管理", icon: IconUsers }, { id: "accounts", label: "账号管理", icon: IconUser }, { id: "templates", label: "模板管理", icon: IconLayoutGrid }, { id: "usage", label: "使用统计", icon: IconChartBar }];
const section = computed({ get: () => sections.some(item => item.id === route.query.section) ? String(route.query.section) : "customers", set: value => { void router.push({ path: "/admin", query: { section: value } }); } });
function openAccounts(customerId: string) { void router.push({ path: "/admin", query: { section: "accounts", customerId } }); }
const customerSearch = ref("");
const filteredCustomers = computed(() => state.value.customers.filter(item => item.name.includes(customerSearch.value.trim())));
const busy = ref(false), dialogError = ref("");
const customerVisible = ref(false), customerDraft = ref<Customer>();
const templateVisible = ref(false), templateDraft = ref<PlatformTemplate>();
const templateFileInput = ref<HTMLInputElement>(), templateFile = ref<File>();
const usageCustomer = ref(""), usageAccount = ref(""), usageModel = ref(""), usageDates = ref<[Date, Date]>();
const usageAccounts = computed(() => state.value.accounts.filter(item => !usageCustomer.value || item.customerId === usageCustomer.value));
watch(usageCustomer, () => { usageAccount.value = ""; });
const usageTasks = computed(() => state.value.tasks.filter(item => (!usageCustomer.value || item.customerId === usageCustomer.value) && (!usageAccount.value || item.accountId === usageAccount.value) && (!usageModel.value || item.modelId === usageModel.value) && (!usageDates.value || new Date(item.createdAt) >= usageDates.value[0] && new Date(item.createdAt).getTime() < usageDates.value[1].getTime() + 86400000)));
function formatDate(value: string) { return new Date(value).toLocaleString(); }
function clone<T>(value: T): T { return JSON.parse(JSON.stringify(value)); }
function openCustomer(value?: Customer) { customerDraft.value = value ? clone(value) : { id: crypto.randomUUID(), name: "", modelIds: state.value.models.filter(item => item.enabled && item.verified).map(item => item.id), defaults: {} }; dialogError.value = ""; customerVisible.value = true; }
function openTemplate(value?: PlatformTemplate) { templateFile.value = undefined; templateDraft.value = value ? clone(value) : { id: crypto.randomUUID(), name: "", kind: "video", description: "", customerIds: [], modelIds: [], enabled: false }; dialogError.value = ""; templateVisible.value = true; }
async function perform(command: PlatformCommand, close?: () => void) {
  if (busy.value) return; busy.value = true; dialogError.value = "";
  try { await savePlatform(command); close?.(); ElMessage.success(platform.scope === "scenario" ? "演示状态已更新，未写入真实服务" : "操作成功"); }
  catch (cause) { dialogError.value = cause instanceof Error ? cause.message : "保存失败"; ElMessage.error(dialogError.value); }
  finally { busy.value = false; }
}
async function saveCustomer() { if (customerDraft.value) await perform({ type: "customer", value: clone(customerDraft.value) }, () => { customerVisible.value = false; }); }
async function toggleCustomer(customer: Customer) {
  const enabled = customer.enabled === false;
  const confirmed = await ElMessageBox.confirm(enabled ? "解除用户组限制，单独禁用的账号仍保持禁用。" : "该用户组全部账号将暂停登录和提交新任务，已有内容保留。", `${enabled ? "启用" : "禁用"} ${customer.name}？`, { confirmButtonText: "确认", cancelButtonText: "取消", type: "warning" }).then(() => true, () => false);
  if (confirmed) await perform({ type: "customerStatus", id: customer.id, enabled });
}
async function deleteCustomer(customer: Customer) {
  if (state.value.accounts.some(item => item.customerId === customer.id)) { ElMessage.warning("用户组下仍有账号，请先处理账号后再删除用户组"); return; }
  const result = await ElMessageBox.prompt("请输入客户名称确认删除，历史内容与归属保留。", "删除用户组", { inputValidator: value => value === customer.name || "客户名称不匹配", confirmButtonText: "删除", cancelButtonText: "取消", type: "warning" }).catch(() => undefined);
  if (result) await perform({ type: "deleteCustomer", id: customer.id });
}
function pickTemplateFile(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; if (templateDraft.value?.kind === "video" && file.type !== "video/mp4" || templateDraft.value?.kind === "project" && !file.name.toLowerCase().endsWith(".json")) { dialogError.value = "请选择有效的MP4视频或JSON项目快照"; return; } if (file.size > 100 * 1024 * 1024) { dialogError.value = "模板文件不能超过100MB"; return; } templateFile.value = file; dialogError.value = ""; }
async function saveTemplate() { if (templateDraft.value) await perform({ type: "template", value: clone(templateDraft.value), source: templateFile.value }, () => { templateVisible.value = false; }); }
onMounted(loadPlatform);
</script>
<style scoped lang="scss">
.adminPage { min-height:100dvh; background:#131416; color:var(--el-text-color-primary); .adminSidebar { position:fixed; inset:0 auto 0 0; width:232px; background:#191a1d; padding:28px 16px 16px; display:flex; flex-direction:column; gap:20px; box-sizing:border-box; :deep(.brandLogo) { max-width:152px; } .endLabel { font-size:12px; color:var(--el-text-color-secondary); padding-left:12px; } nav { display:grid; gap:4px; flex:1; align-content:start; button { display:flex; align-items:center; gap:12px; border:0; border-radius:8px; padding:12px; background:transparent; color:#b3b8c3; text-align:left; font:inherit; cursor:pointer; &:hover { background:#24262c; } &[aria-current] { color:#c4b6ff; background:#2b2739; } &:focus-visible { outline:2px solid #b6a5ef; outline-offset:2px; } } } }
.adminContent { margin-left:232px; padding:32px; max-width:1600px; .customerActions { display:flex; flex-wrap:nowrap; align-items:center; gap:8px; white-space:nowrap; .el-button { flex:none; margin:0; padding:6px; font-size:13px; } } .pageHeader { display:flex; justify-content:space-between; align-items:center; margin-bottom:32px; .eyebrow { color:#929aaa; font-size:12px; } h1 { font-size:26px; font-weight:500; margin:12px 0 0; } } .sectionToolbar { display:flex; justify-content:space-between; align-items:center; gap:16px; margin:20px 0; > .el-input { max-width:320px; } } p { color:var(--el-text-color-secondary); line-height:1.7; } .modelGrid { display:grid; grid-template-columns:repeat(auto-fill,minmax(280px,1fr)); gap:16px; margin-top:24px; article { padding:24px; border:1px solid #30333b; border-radius:12px; background:#1c1e23; h3 { font-size:18px; font-weight:500; } p { min-height:64px; } code { color:#a7afbd; overflow-wrap:anywhere; } .modelHeading { display:flex; gap:8px; } footer { margin-top:16px; display:flex; flex-wrap:wrap; } } } small { display:block; color:#a0a8b6; } .usageFilters { display:flex; flex-wrap:wrap; gap:12px; >.el-select { width:180px; } } .usageSummary { display:grid; grid-template-columns:repeat(4,1fr); gap:16px; margin:24px 0; article { padding:20px; background:#1c1e23; border-radius:12px; span { color:#a7afbd; } strong { display:block; margin-top:12px; font-size:28px; font-weight:500; font-variant-numeric:tabular-nums; } } } }
:deep(.el-dialog) { margin-top:6dvh; margin-bottom:6dvh; }
:deep(.el-dialog__body) { max-height:70dvh; overflow-y:auto; }
.modelEditor { display:grid; grid-template-columns:minmax(0,1fr) minmax(240px,.7fr); gap:24px; .parameterRow { display:grid; grid-template-columns:1fr 1fr; gap:8px; margin-bottom:16px; strong { grid-column:1/-1; } } .userPreview { padding:20px; background:var(--el-fill-color-light); border-radius:12px; align-self:start; p { color:var(--el-text-color-secondary); line-height:1.7; } } }
.notificationPreview { margin-top:20px; padding:20px; background:var(--el-fill-color-light); border-radius:12px; white-space:pre-wrap; } .failure { color:var(--el-color-danger); }
@media(max-width:800px) { .adminSidebar { width:176px; padding:16px 8px; } .adminContent { margin-left:176px; padding:20px 12px; .pageHeader { align-items:flex-start; gap:12px; flex-wrap:wrap; } .usageSummary { grid-template-columns:repeat(2,1fr); } } .modelEditor { grid-template-columns:1fr; } }
}
</style>
